<?php $page_title='Detail layanan';$this->load->view('staff/_layout_start',compact('user','page_title')); ?>
<section class="staff-hero"><div><span class="staff-kicker"><?= html_escape($ticket['reference_no']) ?></span><h1><?= html_escape($ticket['subject']) ?></h1><p><?= html_escape(($types[$ticket['ticket_type']]??$ticket['ticket_type']).' · '.($statuses[$ticket['status']]??$ticket['status'])) ?></p></div></section>
<?php if($this->input->get('terkirim') || $this->input->get('tersimpan')): ?><div class="alert alert-success">Permohonan berhasil disimpan.</div><?php endif; ?>
<section class="staff-panel"><h2>Permohonan</h2><p>Pemohon: <?= html_escape($ticket['requester_name']) ?> · Kegiatan: <?= html_escape($ticket['business_name']?:'Tidak dipilih') ?> · Dikirim: <?= html_escape($ticket['created_at']) ?></p><p><?= nl2br(html_escape($ticket['description'])) ?></p><p>Petugas: <?= html_escape($ticket['assignee_name']?:'Belum ditugaskan') ?></p></section>
<section class="staff-panel"><h2>Riwayat tindak lanjut</h2><?php foreach($updates as $item): ?><article class="staff-panel"><strong><?= html_escape($item['actor_name']?:'Sistem') ?></strong> · <?= html_escape($item['created_at']) ?> · <?= html_escape($statuses[$item['new_status']]??$item['new_status']) ?><?php if($user['role_code']!=='umkm'): ?> · <?= $item['visibility']==='internal'?'Catatan internal':'Terlihat pemohon' ?><?php endif; ?><p><?= nl2br(html_escape($item['note'])) ?></p></article><?php endforeach; ?></section>
<?php if($user['role_code']==='umkm' && !in_array($ticket['status'],array('completed','rejected'),TRUE)): ?><section class="staff-panel"><h2>Balas petugas</h2><form method="post" action="<?= site_url('pengelola/layanan/'.$ticket['id'].'/tindak-lanjut') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label class="form-label">Catatan<textarea class="form-control" name="note" minlength="10" maxlength="3000" required rows="4"></textarea></label><button class="btn btn-primary" type="submit">Kirim balasan</button></form></section><?php endif; ?>
<?php if($user['role_code']!=='umkm'): ?><section class="staff-panel"><h2>Tindak lanjut petugas</h2><form method="post" action="<?= site_url('pengelola/layanan/'.$ticket['id'].'/tindak-lanjut') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label class="form-label">Status<select class="form-select" name="status"><?php foreach($statuses as $value=>$label): if($value==='submitted')continue; ?><option value="<?= $value ?>" <?= $ticket['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php if(in_array($user['role_code'],array('superadmin','admin_dinas'),TRUE)): ?><label class="form-label">Petugas<select class="form-select" name="assigned_to"><option value="">Belum ditugaskan</option><?php foreach($staff as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (int)$ticket['assigned_to']===(int)$item['id']?'selected':'' ?>><?= html_escape($item['full_name']) ?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="assigned_to" value="<?= (int)$ticket['assigned_to'] ?>"><?php endif; ?><label class="form-label">Tampilan catatan<select class="form-select" name="visibility"><option value="public">Terlihat pemohon</option><option value="internal">Hanya petugas</option></select></label><label class="form-label">Catatan tindak lanjut<textarea class="form-control" name="note" minlength="10" maxlength="3000" required rows="4"></textarea></label><button class="btn btn-primary" type="submit">Simpan tindak lanjut</button></form></section><?php endif; ?>
<?php $this->load->view('staff/_layout_end'); ?>
